#!/usr/bin/env node
import { readFileSync, writeFileSync, existsSync, mkdirSync } from "node:fs";
import { dirname } from "node:path";

const HEADER =
  "// Generated by scripts/vscode.sh - edit code/settings.base.jsonc or the local overlay instead.";

function stripJsonc(text) {
  let out = "";
  let i = 0;
  while (i < text.length) {
    const c = text[i];
    if (c === '"') {
      let j = i + 1;
      while (j < text.length) {
        if (text[j] === "\\") j += 2;
        else if (text[j] === '"') break;
        else j++;
      }
      out += text.slice(i, j + 1);
      i = j + 1;
    } else if (c === "/" && text[i + 1] === "/") {
      while (i < text.length && text[i] !== "\n") i++;
    } else if (c === "/" && text[i + 1] === "*") {
      i += 2;
      while (i < text.length && !(text[i] === "*" && text[i + 1] === "/")) i++;
      i += 2;
    } else {
      out += c;
      i++;
    }
  }
  return out.replace(/,(\s*[}\]])/g, "$1");
}

function readJsonc(path, fallback) {
  if (!existsSync(path)) return fallback;
  const raw = readFileSync(path, "utf8").replace(/^﻿/, "").trim();
  if (!raw) return fallback;
  try {
    return JSON.parse(stripJsonc(raw));
  } catch (err) {
    throw new Error(`${path}: ${err.message}`);
  }
}

function writeJson(path, value) {
  mkdirSync(dirname(path), { recursive: true });
  writeFileSync(path, HEADER + "\n" + JSON.stringify(value, null, 4) + "\n");
}

const isObject = (v) => v !== null && typeof v === "object" && !Array.isArray(v);
const equal = (a, b) => JSON.stringify(a) === JSON.stringify(b);

// Local values win. A null local value is a tombstone: it deletes the base key.
function merge(base, local) {
  const out = {};
  for (const key of Object.keys(base)) {
    if (key in local) {
      if (local[key] === null) continue;
      out[key] = isObject(base[key]) && isObject(local[key]) ? merge(base[key], local[key]) : local[key];
    } else {
      out[key] = base[key];
    }
  }
  for (const key of Object.keys(local)) {
    if (key in base || local[key] === null) continue;
    out[key] = local[key];
  }
  return out;
}

// Same shape as merge(), but nulls are stored rather than applied, so a
// deletion survives in the overlay instead of vanishing from it.
function applyPatch(target, patch) {
  const out = { ...target };
  for (const key of Object.keys(patch)) {
    out[key] =
      isObject(out[key]) && isObject(patch[key]) ? applyPatch(out[key], patch[key]) : patch[key];
  }
  return out;
}

// Everything the live file has that the snapshot did not, as a minimal patch.
// Keys the snapshot had and the live file dropped become null tombstones.
function drift(snapshot, live) {
  const patch = {};
  for (const key of Object.keys(live)) {
    if (!(key in snapshot)) {
      patch[key] = live[key];
    } else if (isObject(snapshot[key]) && isObject(live[key])) {
      const nested = drift(snapshot[key], live[key]);
      if (Object.keys(nested).length) patch[key] = nested;
    } else if (!equal(snapshot[key], live[key])) {
      patch[key] = live[key];
    }
  }
  for (const key of Object.keys(snapshot)) {
    if (!(key in live)) patch[key] = null;
  }
  return patch;
}

function flatten(obj, prefix = "") {
  const rows = [];
  for (const [key, value] of Object.entries(obj)) {
    const path = prefix ? `${prefix}.${key}` : key;
    if (isObject(value) && Object.keys(value).length) rows.push(...flatten(value, path));
    else rows.push([path, value]);
  }
  return rows;
}

// Setting keys contain dots ("window.zoomLevel"), so a dotted path is ambiguous.
// Match the whole key literally first, then descend into any object key that is a
// prefix of it.
function findPath(obj, key) {
  if (!isObject(obj)) return null;
  if (key in obj) return [key];
  for (const k of Object.keys(obj)) {
    if (key.startsWith(k + ".")) {
      const rest = findPath(obj[k], key.slice(k.length + 1));
      if (rest) return [k, ...rest];
    }
  }
  return null;
}

function lookup(obj, parts) {
  let cursor = obj;
  for (const part of parts) {
    if (!isObject(cursor) || !(part in cursor)) return { found: false };
    cursor = cursor[part];
  }
  return { found: true, value: cursor };
}

function unset(obj, parts) {
  const [head, ...rest] = parts;
  if (!(head in obj)) return false;
  if (!rest.length) {
    delete obj[head];
    return true;
  }
  const removed = unset(obj[head], rest);
  if (removed && !Object.keys(obj[head]).length) delete obj[head];
  return removed;
}

function syncSettings({ base, local, snapshot, live }) {
  const baseObj = readJsonc(base, {});
  const localObj = readJsonc(local, {});
  const snapObj = readJsonc(snapshot, null);
  const liveObj = readJsonc(live, null);

  let captured = {};
  // With no snapshot there is no common ancestor, so nothing can be attributed
  // to this machine without also swallowing the whole base.
  if (snapObj !== null && liveObj !== null) {
    captured = drift(snapObj, liveObj);
    if (Object.keys(captured).length) writeJson(local, applyPatch(localObj, captured));
  }

  const merged = merge(baseObj, readJsonc(local, {}));
  writeJson(live, merged);
  writeJson(snapshot, merged);
  return flatten(captured).map(([k]) => k);
}

function syncKeybindings({ base, local, snapshot, live }) {
  const baseArr = readJsonc(base, []);
  const localArr = readJsonc(local, []);
  const snapArr = readJsonc(snapshot, null);
  const liveArr = readJsonc(live, null);

  let added = [];
  if (snapArr !== null && liveArr !== null) {
    const known = new Set(snapArr.map((e) => JSON.stringify(e)));
    added = liveArr.filter((e) => !known.has(JSON.stringify(e)));
    if (added.length) writeJson(local, [...localArr, ...added]);
  }

  // VS Code applies the last matching entry, so local trailing entries override base.
  const merged = [...baseArr, ...readJsonc(local, [])];
  writeJson(live, merged);
  writeJson(snapshot, merged);
  return added.map((e) => e.key ?? "(unkeyed)");
}

function status({ base, local }) {
  const baseObj = readJsonc(base, {});
  const localObj = readJsonc(local, {});
  const rows = [];

  // Keybindings are a flat array; a local entry shadows a base one when it binds
  // the same chord, because VS Code applies the last match.
  if (Array.isArray(localObj)) {
    const baseKeys = new Set((baseObj || []).map((e) => e.key));
    for (const entry of localObj) {
      rows.push({
        key: entry.key ?? "(unkeyed)",
        local: JSON.stringify(entry.command ?? entry),
        base: baseKeys.has(entry.key) ? "bound in baseline" : "(not in baseline)",
        shadowing: baseKeys.has(entry.key),
      });
    }
    return rows;
  }

  for (const [path, value] of flatten(localObj)) {
    const parts = findPath(baseObj, path);
    const hit = parts ? lookup(baseObj, parts) : { found: false };
    rows.push({
      key: path,
      local: value === null ? "(removed)" : JSON.stringify(value),
      base: hit.found ? JSON.stringify(hit.value) : "(not in baseline)",
      shadowing: hit.found,
    });
  }
  return rows;
}

const [command, ...rest] = process.argv.slice(2);
const opts = Object.fromEntries(rest.map((a) => a.split(/=(.*)/s).slice(0, 2)));

try {
  if (command === "sync-settings") {
    syncSettings(opts).forEach((k) => console.log(k));
  } else if (command === "sync-keybindings") {
    syncKeybindings(opts).forEach((k) => console.log(k));
  } else if (command === "status") {
    console.log(JSON.stringify(status(opts)));
  } else if (command === "forget") {
    const localObj = readJsonc(opts.local, {});
    const parts = findPath(localObj, opts.key);
    const removed = parts ? unset(localObj, parts) : false;
    if (removed) writeJson(opts.local, localObj);
    process.exit(removed ? 0 : 1);
  } else if (command === "check") {
    readJsonc(opts.file, {});
  } else {
    throw new Error(`unknown command: ${command}`);
  }
} catch (err) {
  console.error(err.message);
  process.exit(1);
}
